def merge(basis, a, b):
    erg, konflikte = {}, []
    for k in basis:
        if a[k] == b[k]:
            erg[k] = a[k]
        elif a[k] == basis[k]:
            erg[k] = b[k]       # nur b änderte
        elif b[k] == basis[k]:
            erg[k] = a[k]       # nur a änderte
        else:
            erg[k] = basis[k]
            konflikte.append(k)
    return erg, konflikte

basis = {"fach": "NVS", "datum": "3.2.",
         "raum": "E12"}
handy = {"fach": "NVS", "datum": "5.2.",
         "raum": "E12"}
laptop = {"fach": "NVS", "datum": "4.2.",
          "raum": "E14"}
print(merge(basis, handy, laptop))

